s($,"fAV","eHj",()=>J.a7(t.P.a(A.K6('{"interests": {"in_art": {"name": "art"}, "in_books": {"name": "books"}, "in_climbing": {"name": "climbing"}, "in_coffee": {"name": "coffee"}, "in_cooking": {"name": "cooking"}, "in_film": {"name": "film"}, "in_hiking": {"name": "hiking"}, "in_music": {"name": "music"}, "in_running": {"name": "running"}, "in_travel": {"name": "travel"}}, "matches": {"m_1": {"a": "pr_jordan", "b": "pr_morgan", "note": "Both love hiking.", "status": "matched"}, "m_2": {"a": "pr_riley", "b": "pr_taylor", "note": "Music in common.", "status": "liked"}, "m_3": {"a": "pr_casey", "b": "pr_jordan", "note": "Different schedules.", "status": "passed"}, "m_4": {"a": "pr_avery", "b": "pr_emery", "note": "Runners who both rank coffee shops by espresso quality. First date set for Saturday.", "status": "matched"}, "m_5": {"a": "pr_quinn", "b": "pr_sage", "note": "Argued about a film adaptation for an hour and loved it.", "status": "matched"}, "m_6": {"a": "pr_rowan", "b": "pr_hayden", "note": "Rowan liked the climbing photos from Kalymnos.", "status": "liked"}, "m_7": {"a": "pr_blake", "b": "pr_sage", "note": "Bonded over jazz biographies in the prompts.", "status": "liked"}, "m_8": {"a": "pr_taylor", "b": "pr_quinn", "note": "Vinyl vs. film schedules never lined up.", "status": "passed"}}, "profiles": {"pr_avery": {"age": 30, "bio": "Half-marathoner training for a full. My ideal first date involves espresso and a long walk to nowhere in particular.", "interests": ["in_running", "in_coffee"], "name": "Avery", "photo": ""}, "pr_blake": {"age": 38, "bio": "Touring jazz bassist settling back home. Looking for someone to drag to live shows and tiny noodle bars.", "interests": ["in_music", "in_books"], "name": "Blake", "photo": ""}, "pr_casey": {"age": 27, "bio": "Gallery hopper and slow traveler. Will talk about color theory for hours.", "interests": ["in_art", "in_travel"], "name": "Casey", "photo": ""}, "pr_emery": {"age": 25, "bio": "Pastry cook at a small bakery \u2014 yes, I will bring croissants on the second date. Runner, but only when it\'s under 25 degrees.", "interests": ["in_cooking", "in_running", "in_coffee"], "name": "Emery", "photo": ""}, "pr_hayden": {"age": 32, "bio": "Backpacked four continents, now planning the fifth. Fluent in three languages and bad puns in all of them.", "interests": ["in_travel", "in_climbing", "in_books"], "name": "Hayden", "photo": ""}, "pr_jordan": {"age": 29, "bio": "Weekend trail hiker and amateur photographer. Always chasing a good view.", "interests": ["in_hiking", "in_travel"], "name": "Jordan", "photo": ""}, "pr_morgan": {"age": 34, "bio": "Home cook, hiker, and weekend museum wanderer.", "interests": ["in_cooking", "in_hiking", "in_art"], "name": "Morgan", "photo": ""}, "pr_quinn": {"age": 33, "bio": "Film school dropout, now a barista with strong opinions on both pour-overs and third acts. Tuesday matinees are sacred.", "interests": ["in_film", "in_coffee", "in_art"], "name": "Quinn", "photo": ""}, "pr_riley": {"age": 31, "bio": "Plays in a local band and cooks way too much pasta. Looking for a duet partner.", "interests": ["in_music", "in_cooking"], "name": "Riley", "photo": ""}, "pr_rowan": {"age": 28, "bio": "Found bouldering during the pandemic and never looked back. Will belay you through your first top-rope climb, promise.", "interests": ["in_climbing", "in_hiking"], "name": "Rowan", "photo": ""}, "pr_sage": {"age": 35, "bio": "Librarian by day, book club tyrant by night. Currently reading three novels at once and finishing none of them.", "interests": ["in_books", "in_film"], "name": "Sage", "photo": ""}, "pr_taylor": {"age": 26, "bio": "Vinyl collector and aspiring world traveler. Recommend me a record.", "interests": ["in_music", "in_travel"], "name": "Taylor", "photo": ""}}}\n')),t.N,t.z))
